/* Gym Board's independent presentation layer. All persistent actions are cancelable. */
(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const escape = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const fmt = n => Number(n || 0).toLocaleString('en-US', {maximumFractionDigits:1});
  const dateObj = s => new Date(`${s}T12:00:00`);
  const dateKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const addDays = (s,n) => { const d=dateObj(s); d.setDate(d.getDate()+n); return dateKey(d); };
  const prettyDate = (s, options={month:'short',day:'numeric'}) => dateObj(s).toLocaleDateString('en-US',options);
  const iconPaths = {
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="2"/><circle cx="16" cy="17" r="2"/>',minus:'<path d="M5 12h14"/>',plus:'<path d="M12 5v14M5 12h14"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', check:'<path d="m5 12 4 4L19 6"/>',
    today:'<circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/>',board:'<path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/>',
    history:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4M16 3v4M4 10h16M8 14h2M14 14h2M8 17h2"/>',
    weight:'<path d="M3 18h18M4 13l5-5 4 4 7-8M16 4h4v4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',
    moon:'<path d="M20 14.5A8.5 8.5 0 0 1 9.5 4 8.5 8.5 0 1 0 20 14.5Z"/>',
    dumbbell:'<path d="M7 9h10M7 15h10M3 9v6M6 6v12M18 6v12M21 9v6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
    edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2.1 2.1 0 0 0-3-3L5 17l-1 3Z"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v6M14 10v6"/>',
    scale:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 9a5 5 0 0 1 8 0l-4 4-4-4ZM12 8v4"/>',rest:'<path d="M6 4v16M18 4v16M5 10h14M5 17h14M9 7h6"/>',
    pause:'<path d="M8 5v14M16 5v14"/>',away:'<path d="m3 15 7-3 6-8 2 1-4 9 6 2-1 2-7-1-5 4-1-1 3-5-6 2Z"/>',
    reset:'<path d="M4 9a8 8 0 1 1 0 6M4 4v5h5"/>',collapse:'<path d="m5 15 7-7 7 7"/>',expand:'<path d="m5 9 7 7 7-7"/>',bolt:'<path d="m13 2-8 12h6l-1 8 9-13h-6l1-7Z"/>'
  };
  const icon = (name, attrs='') => `<svg viewBox="0 0 24 24" aria-hidden="true" ${attrs}>${iconPaths[name] || iconPaths.plus}</svg>`;
  const today='2026-09-07';
  const demoMeals=[{id:'m1',name:'Eggs & sourdough',calories:540,protein:32,time:'8:42 AM'},{id:'m2',name:'Chicken rice bowl',calories:780,protein:54,time:'12:16 PM'},{id:'m3',name:'Huel Black',calories:500,protein:42,time:'3:30 PM'}];
  const demoMembers=[['soren','Soren',12,86],['alex','Alex',8,93],['maya','Maya',5,79],['jordan','Jordan',3,71]].map(([id,name,streak,compliance],i)=>({id,name,emoji:name[0],streak,compliance,lastActivity:i===0?'Just now':`${i+1}h ago`,weightDelta:1.2-i*.5,days:[],daysByDate:{}}));
  const demoWeights=demoMembers.slice(0,3).map((member,i)=>({id:member.id,name:member.name,points:Array.from({length:70},(_,j)=>({date:addDays(today,j-69),value:Math.round(((169.4+i*12)-(69-j)*.028+Math.sin(j*1.13+i)*.48)*10)/10}))}));
  let state={ready:false,demo:false,view:'today',today,selectedDate:today,connection:'Saved',user:{id:'soren',name:'Soren',emoji:'S',calorieGoal:3000,proteinGoal:180,nutritionMode:'both',goal:'gain',weightPrivate:false,rolloverHour:4,restDays:[0],workoutTypes:['Upper','Lower'],paused:false,vacations:[]},day:{date:today,calories:1820,protein:128,nutritionHit:false,nutritionManual:false,workout:false,workoutType:'Upper',rest:false,scheduledRest:false,paused:false,vacation:false,weight:169.4,weightDate:today,meals:demoMeals,editable:true},presets:[{id:'p1',name:'Huel Black',calories:400,protein:40,note:'2 scoops'},{id:'p2',name:'Protein bar',calories:190,protein:21,note:''},{id:'p3',name:'Greek yogurt',calories:140,protein:20,note:''}],members:demoMembers,weights:demoWeights,weekOffset:0,historyMonth:'2026-09',historyMember:'soren',chartRange:90,chartMode:'relative',chartExpanded:true,theme:localStorage.getItem('gymboard.theme')||'dark'};
  let toastTimer, sheetContext={}, chartZoom=1, chartPan=0;
  let quickMealDraft={name:'',calories:'',protein:''};
  let saveSequence=0,settingsInstance='';
  const saveOperations=new Map();
  const nextSaveId=()=>`save-${Date.now().toString(36)}-${++saveSequence}`;
  const pendingSave=op=>op.status==='saving'||op.status==='pending';
  function formDraft(form){return $$('input[name],select[name],textarea[name]',form).map(el=>({name:el.name,type:el.type,value:el.value,checked:el.checked}));}
  function restoreDraft(form,draft){for(const field of draft||[]){const el=$$('input[name],select[name],textarea[name]',form).find(el=>el.name===field.name);if(!el)continue;if(field.type==='checkbox'||field.type==='radio')el.checked=field.checked;else el.value=field.value;}}
  function bindSaveForms(){
    $$('[data-quick-meal]').forEach(form=>form.dataset.saveInstance=`quick:${state.today}`);
    if($('#action-sheet').open)$$('form', $('#action-sheet')).forEach(form=>form.dataset.saveInstance=sheetContext.instance);
    if($('#settings-drawer').open)$$('form', $('#settings-drawer')).forEach(form=>form.dataset.saveInstance=`${settingsInstance}:${form.dataset.form}`);
  }
  function operationForm(op){return $$('form[data-save-instance]').find(form=>form.dataset.saveInstance===op.instance&&(!form.closest('dialog')||form.closest('dialog').open));}
  function operationAttached(op){return op.formType?!!operationForm(op):op.sheetInstance&&$('#action-sheet').open&&sheetContext.instance===op.sheetInstance;}
  function retainEditedDraft(event){const form=event.target.closest('form[data-save-instance]');if(!form)return;for(const op of saveOperations.values())if(op.instance===form.dataset.saveInstance&&!pendingSave(op))op.draft=formDraft(form);}
  document.addEventListener('input',retainEditedDraft);
  document.addEventListener('change',retainEditedDraft);
  function setFormBusy(form,op){
    const busy=pendingSave(op);
    $$('input,select,textarea,button',form).forEach(el=>{
      if(busy){if(el.dataset.saveDisabled===undefined)el.dataset.saveDisabled=String(el.disabled);el.disabled=true;}
      else if(el.dataset.saveDisabled!==undefined){el.disabled=el.dataset.saveDisabled==='true';delete el.dataset.saveDisabled;}
    });
    const button=$('button[type=submit]',form);
    if(button){if(busy){if(button.dataset.idleLabel===undefined)button.dataset.idleLabel=button.innerHTML;button.textContent=op.status==='pending'?'Pending…':'Saving…';}else if(button.dataset.idleLabel!==undefined){button.innerHTML=button.dataset.idleLabel;delete button.dataset.idleLabel;}}
    let message=$('.form-error',form);
    if(!message){message=document.createElement('p');message.className='form-error';form.append(message);}
    message.setAttribute('role',op.status==='error'||op.status==='partial'?'alert':'status');
    message.dataset.saveStatus=op.status;
    message.textContent=op.message||(op.status==='pending'?'Save pending. Your draft is retained until confirmation.':op.status==='error'?'Could not save. Your draft is ready to retry.':op.status==='partial'?'Some fields saved. Review the remaining fields and retry.':'');
  }
  function renderSaveRecovery(){
    const host=$('#save-recovery');if(!host)return;
    const detached=[...saveOperations.values()].filter(op=>op.formType&&!operationAttached(op));
    host.hidden=!detached.length;
    host.innerHTML=detached.map(op=>`<div class="save-recovery-row"><span><strong>${escape(({meal:'Food entry',preset:'Saved meal',weight:'Weight',catchup:'Day nutrition',goals:'Nutrition targets',profile:'Profile',vacation:'Vacation',reclaim:'Device access'})[op.formType]||'Entry')}</strong> ${escape(op.message||(pendingSave(op)?'Save pending. Draft retained.':'Draft retained. Review and retry.'))}</span><button class="secondary-button" data-action="recover-save" data-operation-id="${escape(op.id)}">${pendingSave(op)?'View pending entry':'Recover draft'}</button></div>`).join('');
  }
  function syncOperationUI(){
    bindSaveForms();
    const byForm=new Map();for(const op of saveOperations.values()){const previous=byForm.get(op.instance);if(!previous||pendingSave(op)||!pendingSave(previous))byForm.set(op.instance,op);}
    for(const op of byForm.values()){const form=operationForm(op);if(form){if(pendingSave(op))restoreDraft(form,op.draft);setFormBusy(form,op);}}
    renderSaveRecovery();
  }
  function recoverSave(id){
    const op=saveOperations.get(id);if(!op)return;
    // Never replace a newer draft that is already open.
    if($('#action-sheet').open||$('#settings-drawer').open){notify('Close the current form to recover this draft.');return;}
    if(op.settingsInstance){openSettings();op.instance=`${settingsInstance}:${op.formType}`;op.settingsInstance=settingsInstance;}
    else {openSheet(op.context.type||op.formType,op.context);op.instance=sheetContext.instance;op.sheetInstance=sheetContext.instance;}
    const form=operationForm(op);if(form)restoreDraft(form,op.draft);
    syncOperationUI();
  }
  function beginSave(action,payload,source){
    bindSaveForms();
    const form=source?.closest('form[data-form]');
    const sheet=source?.closest('#action-sheet'),drawer=source?.closest('#settings-drawer');
    const id=nextSaveId();payload={...payload,_operationId:id};
    const op={id,action,payload,status:'saving',formType:form?.dataset.form,instance:form?.dataset.saveInstance,sheetInstance:sheet?sheetContext.instance:null,settingsInstance:drawer?settingsInstance:null,parentSettings:$('#settings-drawer').open?settingsInstance:null,context:sheet?{...sheetContext}:{type:form?.dataset.form,date:payload.date},draft:form?formDraft(form):[],quickDraft:{...quickMealDraft},quick:!!form?.dataset.quickMeal,fromQuick:!!sheet?.open&&!!sheetContext.fromQuick};
    // A retry replaces only this same form's settled failure, never an active save.
    for(const [oldId,old] of saveOperations)if(op.instance&&old.instance===op.instance&&!pendingSave(old))saveOperations.delete(oldId);
    saveOperations.set(id,op);syncOperationUI();return payload;
  }
  function demoDays(){state.members.forEach((m,mi)=>{for(let i=-60;i<=0;i++){let date=addDays(state.today,i);let rest=dateObj(date).getDay()===0; m.daysByDate[date]={date,workout:!rest && (i+mi)%5!==0,workoutType:(i%2?'Upper':'Lower'),rest,nutritionHit:(i+mi)%6!==0,calories:2400+((i*137+mi*40)%600),protein:145+Math.abs(i*17%40),editable:m.id===state.user.id,own:m.id===state.user.id,meals:[],calorieGoal:3000,proteinGoal:180};} }); refreshDemoWeek();}
  function refreshDemoWeek(){const weekday=(dateObj(state.today).getDay()+6)%7;const start=addDays(state.today,-weekday+state.weekOffset*7);state.members.forEach(m=>m.days=Array.from({length:7},(_,i)=>{const date=addDays(start,i);return {...(m.daysByDate[date]||{date}),future:date>state.today,own:m.id===state.user.id,editable:m.id===state.user.id&&date<=state.today};}));}
  demoDays();
  function goals(day=state.day){return{calories:Number(day.calorieGoal??state.user.calorieGoal)||0,protein:Number(day.proteinGoal??state.user.proteinGoal)||0};}
  function dayFor(date,memberId=state.user.id){if(date===state.today&&memberId===state.user.id)return state.day;const member=state.members.find(m=>m.id===memberId);return member?.daysByDate?.[date]||member?.days?.find(d=>d.date===date)||{date,calories:0,protein:0,meals:[],editable:memberId===state.user.id&&date<=state.today};}
  function notify(message,error=false){const toast=$('#toast');toast.textContent=message;toast.classList.toggle('error',error);toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),3000);}
  function dispatch(action,payload={},source=null){if(!['navigate','change-week','change-month','change-member','retry'].includes(action))payload=beginSave(action,payload,source);const event=new CustomEvent('gymboard:action',{detail:{action,payload},cancelable:true});if(!window.dispatchEvent(event))return event.detail.promise||false;demoAction(action,payload);return true;}
  function presetChips(){return state.presets.map(p=>`<button class="preset-chip" data-action="log-preset" data-id="${escape(p.id)}" title="Log ${escape(p.name||'saved meal')}: ${fmt(p.calories)} calories, ${fmt(p.protein)}g protein">${icon('plus')}<span>${escape(p.name||'Saved meal')}</span><small>${fmt(p.calories)}</small></button>`).join('');}
  function nutritionText(day){if(day.dataUnavailable)return'Unavailable';const g=goals(day);if(day.vacation)return'Away';if(day.nutritionManual)return'Marked complete';if(day.nutritionStatus==='hit')return'Target reached';if(day.nutritionStatus==='missed')return'Target missed';if(day.prejoin)return'Before joining';return'In progress';}
  function nutritionReadout(){
    const d=state.day,g=goals(),mode=state.user.nutritionMode;
    if(mode==='manual')return `<div class="manual-panel"><div class="manual-status">${d.nutritionManual?'Marked complete':'Not marked complete'}</div><p>Manual completion does not change your recorded calories or protein.</p><button class="manual-completion ${d.nutritionManual?'done':''}" data-action="toggle-nutrition">${icon(d.nutritionManual?'check':'plus')}<span>${d.nutritionManual?'Undo completion':'Complete nutrition'}</span></button></div>`;
    const proteinOnly=mode==='protein',current=Number(proteinOnly?d.protein:d.calories)||0,target=proteinOnly?g.protein:g.calories,ratio=target>0?current/target:0,unit=proteinOnly?'g':'kcal';
    const segments=Array.from({length:48},(_,i)=>`<i class="${i<Math.round(Math.min(1,ratio)*48)?'on':''}"></i>`).join('');
    return `<div class="big-reading"><strong class="calorie-number" data-total="${current}">${fmt(current)}</strong><span>${unit}</span></div><div class="energy-meter" role="meter" aria-label="${proteinOnly?'Protein':'Calories'}" aria-valuemin="0" aria-valuemax="${Math.max(target,current,1)}" aria-valuenow="${current}" aria-valuetext="${fmt(current)} of ${fmt(target)} ${unit}">${segments}</div><div class="range">${[0,.25,.5,.75,1].map(f=>`<span>${fmt(Math.round(target*f))}</span>`).join('')}</div><div class="target-details"><div><small>${current>target?'Over target':'Remaining'}</small><strong>${fmt(Math.abs(target-current))} <small>${unit}</small></strong></div><div><small>Daily target</small><strong>${fmt(target)} <small>${unit}</small></strong></div></div>`;
  }
  function renderToday(){renderTodayContent();syncOperationUI();}
  function renderTodayContent(){
    const d=state.day,g=goals(),mode=state.user.nutritionMode,meals=d.meals||[];
    const focusId=document.activeElement?.closest('[data-quick-meal]')?document.activeElement.id:null;
    const heading=`<div class="page-heading"><div class="heading-group"><h1 class="page-title">Today</h1><span class="heading-date">${prettyDate(state.today,{weekday:'short',month:'short',day:'numeric'})}</span></div><button class="add-button top-log-button" data-action="open-meal" ${d.dataUnavailable?'disabled':''}>${icon('plus')}Log food</button></div>`;
    if(d.dataUnavailable){$('#today-view').innerHTML=heading+`<div class="unavailable-state"><h2>Today’s records are unavailable</h2><p>Reload your records before making changes.</p><button class="primary-button" data-action="retry">Try again</button></div>`;return;}
    const rest=d.rest||d.scheduledRest;
    const workoutStatus=d.workout?'Workout complete':d.vacation?'On vacation':d.paused?'Workouts paused':d.rest?'Rest day':d.scheduledRest?'Scheduled rest':'Workout not logged';
    const workoutButton=d.workout?'Workout done · Undo':d.vacation?'Vacation settings':d.paused?'Resume workouts':d.rest?'Rest options':'Mark workout done';
    const workoutName=d.workout?(d.workoutType||'Workout'):d.vacation?'Vacation':d.paused?'Paused':rest?'Rest':(d.workoutType||'Workout');
    const canChooseType=!d.workout&&!rest&&!d.paused&&!d.vacation;
    const numericCurrent=mode==='protein'?Number(d.protein)||0:Number(d.calories)||0,numericTarget=mode==='protein'?g.protein:g.calories;
    const progressLabel=d.nutritionManual?'Manually marked complete':mode==='manual'?nutritionText(d):numericTarget>0?`${Math.round(numericCurrent/numericTarget*100)}% of target`:'No target set';
    const pending=false;
    $('#today-view').innerHTML=heading+`<div class="day-layout"><section class="nutrition" aria-label="Daily nutrition and training"><div class="nutrition-head"><span>${mode==='manual'?'Nutrition':mode==='protein'?'Protein':'Calories'}</span><button class="nutrition-status" data-action="nutrition-options" aria-label="Nutrition completion options"><span>${escape(progressLabel)}</span></button></div>${nutritionReadout()}${mode==='both'?`<div class="protein"><div class="protein-head"><span>Protein</span><strong>${fmt(d.protein)} <span>/ ${fmt(g.protein)} g</span></strong></div><div class="protein-meter" role="meter" aria-label="Protein" aria-valuemin="0" aria-valuemax="${Math.max(g.protein,Number(d.protein)||0,1)}" aria-valuenow="${Number(d.protein)||0}" aria-valuetext="${fmt(d.protein)} of ${fmt(g.protein)} grams"><i style="width:${Math.min(100,g.protein>0?(Number(d.protein)||0)/g.protein*100:0)}%"></i></div><div class="protein-note">${fmt(Math.abs(g.protein-(Number(d.protein)||0)))} g ${d.protein>g.protein?'over target':'remaining'}</div></div>`:''}${d.nutritionManual&&mode!=='manual'?'<p class="manual-note">Completion is manual. Totals show recorded intake.</p>':''}<div class="workout"><div class="workout-label"><span class="workout-symbol">${icon(d.workout?'check':d.vacation?'away':d.paused?'pause':rest?'rest':'dumbbell')}</span><div class="workout-type">${canChooseType?`<select class="inline-select" data-change="workout-type" aria-label="Workout type"><option value="">Workout</option>${(state.user.workoutTypes||[]).map(t=>`<option value="${escape(t)}" ${d.workoutType===t?'selected':''}>${escape(t)}</option>`).join('')}</select>`:escape(workoutName)}<small>${escape(workoutStatus)}</small></div></div><button class="workout-button workout-orb ${d.workout?'done completed':''}" data-action="toggle-workout" aria-label="${escape(workoutButton)}">${icon(d.workout?'check':d.vacation?'away':d.paused?'pause':d.rest?'rest':'check')}<span>${escape(workoutButton)}</span></button></div><div class="training-actions">${d.paused?'<button class="text-button" data-action="resume-workouts">Resume today</button>':!d.vacation?`<button class="text-button" data-action="set-rest">${rest?'Rest options':'Take a rest day'}</button>`:'<span></span>'}<button class="text-button" data-action="open-settings" data-section="training">Training plan ${icon('chevron')}</button></div><div class="weight"><span class="weight-label">${icon('scale')}Weight</span><button class="weight-value" data-action="open-weight">${d.weight?`${fmt(d.weight)} <small>lb${d.weightDate&&d.weightDate!==state.today?' / '+prettyDate(d.weightDate):''}</small>`:'Add weigh-in'}${icon(d.weight?'edit':'plus')}</button></div></section><section class="food-panel" aria-label="Food log"><div class="food-title"><h2>Food log</h2><span>${meals.length} ${meals.length===1?'entry':'entries'}</span></div><table class="log-table"><thead><tr><th>Food</th><th>Protein</th><th class="calorie-column">kcal</th></tr></thead><tbody>${meals.length?meals.map(m=>`<tr class="meal-row"><td><div class="meal-name">${escape(m.name||'Food entry')}</div>${m.note||m.time?`<div class="meal-meta">${escape([m.note,m.time].filter(Boolean).join(' / '))}</div>`:''}</td><td>${fmt(m.protein)} g</td><td><div class="meal-value"><span>${fmt(m.calories)}</span><button class="meal-delete" data-action="delete-meal" data-id="${escape(m.id)}" aria-label="Delete ${escape(m.name||'food entry')}">${icon('close')}</button></div></td></tr>`).join(''):`<tr class="empty-log"><td colspan="3">No itemized meals.${d.calories||d.protein?'<br>Earlier logged totals are included below.':'<br>Use Log food to add a meal.'}</td></tr>`}</tbody><tfoot><tr><td>Daily total</td><td>${fmt(d.protein)} g</td><td class="calorie-column">${fmt(d.calories)}</td></tr></tfoot></table>${d.baseCalories||d.baseProtein?'<p class="earlier-totals">Daily totals include earlier entries.</p>':''}<form class="inline-log" data-form="meal" data-quick-meal="true" data-date="${state.today}"><h3>Add an entry</h3><input type="hidden" name="name" value="${escape(quickMealDraft.name)}"><div class="input-row"><div><label for="quick-calories">Calories</label><input id="quick-calories" name="calories" type="number" min="1" max="10000" step="1" inputmode="numeric" placeholder="0" value="${escape(quickMealDraft.calories)}" ${pending?'disabled':''} required></div><div><label for="quick-protein">Protein, g</label><input id="quick-protein" name="protein" type="number" min="0" max="1000" step="0.1" inputmode="decimal" placeholder="0" value="${escape(quickMealDraft.protein)}" ${pending?'disabled':''}></div><button type="submit" class="add-button" aria-label="Log food entry" ${pending?'disabled':''}>${pending?'Saving…':icon('plus')}</button></div><p class="form-error" role="alert"></p><div class="quick-form-actions"><button type="button" class="text-button" data-action="open-meal" data-from-quick="true" ${pending?'disabled':''}>Add meal details</button><button type="button" class="text-button" data-action="save-current-preset" ${pending?'disabled':''}>Save as preset</button></div></form><div class="presets"><div class="presets-label">Saved meals</div><div class="preset-list">${presetChips()||'<button class="text-button" data-action="open-preset">Add saved meal</button>'}</div></div><p class="daily-note"><button class="text-button" data-action="open-catchup">Edit a past day ${icon('chevron')}</button></p></section></div>`;
    if(focusId&&!pending)document.getElementById(focusId)?.focus({preventScroll:true});
  }
  function statusIcon(d){if(d.dataUnavailable)return'minus';return d.workout?'dumbbell':d.vacation?'away':d.paused?'pause':d.rest||d.scheduledRest?'rest':d.prejoin?'minus':d.workoutStatus==='missed'?'close':'plus';}
  function renderBoard(){const weekday=(dateObj(state.today).getDay()+6)%7;const start=state.members[0]?.days?.[0]?.date||addDays(state.today,-weekday+state.weekOffset*7);const dates=Array.from({length:7},(_,i)=>addDays(start,i));$('#board-view').innerHTML=`<div class="page-heading"><div><h1 class="page-title">Board</h1><p class="subline">Weekly workout and nutrition records</p></div><span class="tag">${state.members.length} people</span></div><div class="view-toolbar"><div class="period-controls"><button class="icon-button" data-action="change-week" data-offset="${state.weekOffset-1}" aria-label="Previous week">${icon('left')}</button><span>${prettyDate(start)} – ${prettyDate(addDays(start,6))}</span><button class="icon-button" data-action="change-week" data-offset="${state.weekOffset+1}" aria-label="Next week" ${state.weekOffset>=0?'disabled':''}>${icon('chevron')}</button></div><button class="subtle-button" data-action="change-week" data-offset="0" ${state.weekOffset===0?'disabled':''}>This week</button></div><table class="board-table"><thead><tr><th>Members</th>${dates.map(date=>`<th>${prettyDate(date,{weekday:'short'})}<strong>${dateObj(date).getDate()}</strong></th>`).join('')}<th>Consistency</th></tr></thead><tbody>${state.members.map(member=>`<tr><td><div class="member-title"><span class="member-avatar ${member.id===state.user.id?'own':''}">${escape(member.emoji||member.name?.[0]||'?')}</span><div><div class="member-name">${escape(member.name)}${member.id===state.user.id?'<small>you</small>':''}</div><div class="member-meta">${Number(member.streak)||0} day streak<span class="member-rates">${fmt(member.compliance)}% training<br>${fmt(member.complianceNutrition??member.compliance)}% nutrition</span><span class="member-activity">${escape(member.lastActivity||'')}${member.weightTrend?.dir?` / ${escape(member.weightTrend.dir==='up'?'↑':member.weightTrend.dir==='down'?'↓':'→')}`:''}</span></div></div></div></td>${dates.map(date=>{const d=member.days?.find(x=>x.date===date)||member.daysByDate?.[date]||{date};return`<td><button class="board-cell status-${escape(d.workoutStatus||'open')} nutrition-${escape(d.nutritionStatus||'open')} ${d.workout?'workout':''} ${d.nutritionHit?'fueled':''} ${date>state.today?'future':''} ${date===state.today?'current':''}" data-action="open-day" data-date="${date}" data-member="${escape(member.id)}" aria-label="${escape(member.name)}, ${prettyDate(date)}, ${escape(d.workoutStatus||(d.workout?'workout complete':d.rest?'rest':'no workout'))}, ${escape(d.nutritionStatus||(d.nutritionHit?'nutrition complete':'nutrition incomplete'))}">${icon(statusIcon(d))}<i class="nutrition-mark"></i></button></td>`}).join('')}<td><span class="consistency">${fmt(member.compliance)}<small>%</small><span class="consistency-nutrition">${fmt(member.complianceNutrition??member.compliance)}% nutrition</span></span></td></tr>`).join('')}</tbody></table><div class="board-legend"><span><i class="legend-square"></i>Workout complete</span><span><i class="legend-square fuel"></i>Nutrition complete</span><span><i class="legend-square rest"></i>Rest / paused</span></div><div class="board-bottom"><p>Weekly records</p><small>Select a day to view or edit.</small></div>`;}
  function renderHistory(){const month=state.historyMonth;const first=`${month}-01`;const offset=(dateObj(first).getDay()+6)%7;const count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const member=state.members.find(m=>m.id===state.historyMember)||state.members[0];let cells=Array.from({length:offset},()=>'<span></span>').join('');for(let n=1;n<=count;n++){const date=`${month}-${String(n).padStart(2,'0')}`,d=dayFor(date,member?.id);cells+=`<button class="calendar-day status-${escape(d.workoutStatus||'open')} ${date===state.selectedDate?'selected':''}" data-action="select-date" data-date="${date}" aria-label="${prettyDate(date,{month:'long',day:'numeric',year:'numeric'})}" ${date>state.today?'disabled':''}><span class="calendar-number">${n}</span><span class="calendar-marks">${d.workout?'<i></i>':''}${d.nutritionHit?'<i class="fuel"></i>':''}${d.rest||d.scheduledRest?'<i class="rest"></i>':''}${d.paused?'<i class="paused"></i>':''}${d.vacation?'<i class="away"></i>':''}${d.workoutStatus==='missed'?'<i class="missed"></i>':''}</span></button>`;}
    const selected=dayFor(state.selectedDate,member?.id);$('#history-view').innerHTML=`<div class="page-heading"><div><h1 class="page-title">History</h1><p class="subline">Daily records and historical edits</p></div></div><div class="view-toolbar"><div class="period-controls"><button class="icon-button" data-action="change-month" data-direction="-1" aria-label="Previous month">${icon('left')}</button><span>${prettyDate(first,{month:'long',year:'numeric'})}</span><button class="icon-button" data-action="change-month" data-direction="1" aria-label="Next month" ${month>=state.today.slice(0,7)?'disabled':''}>${icon('chevron')}</button></div><select class="history-person" data-change="history-member" aria-label="History member">${state.members.map(m=>`<option value="${escape(m.id)}" ${m.id===member?.id?'selected':''}>${escape(m.name)}</option>`).join('')}</select></div><div class="calendar-layout"><div><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells}</div><div class="board-legend"><span><i class="legend-square"></i>Workout</span><span><i class="legend-square fuel"></i>Nutrition</span></div></div><aside class="history-preview"><h2 class="preview-date">${prettyDate(state.selectedDate,{weekday:'short',month:'short',day:'numeric'})}</h2><div class="preview-metric"><span>Training</span><strong>${escape(selected.workout?(selected.workoutType||'Complete'):selected.vacation?'Away':selected.paused?'Paused':selected.rest||selected.scheduledRest?'Rest':'Not logged')}</strong></div><div class="preview-metric"><span>Calories</span><strong>${fmt(selected.calories)} kcal</strong></div><div class="preview-metric"><span>Protein</span><strong>${fmt(selected.protein)} g</strong></div><button class="primary-button full-width" data-action="open-day" data-date="${state.selectedDate}" data-member="${escape(member?.id)}">View day ${icon('arrow')}</button>${member?.id===state.user.id&&state.selectedDate<state.today?`<button class="text-button" data-action="open-catchup" data-date="${state.selectedDate}">Fill in nutrition ${icon('chevron')}</button>`:''}</aside></div>`;}
  function visibleSeries(){return(state.weights||[]).filter(s=>s.points?.length).map(series=>({...series,points:series.points.filter(p=>p.date>=addDays(state.today,-state.chartRange))})).filter(s=>s.points.length);}
  function chartData(){const series=visibleSeries();const dates=[...new Set(series.flatMap(s=>s.points.map(p=>p.date)))].sort();let len=Math.max(2,Math.ceil(dates.length/chartZoom));let start=Math.max(0,Math.min(dates.length-len,Math.round(chartPan*(dates.length-len))));const shown=dates.slice(start,start+len);const processed=series.map(s=>({...s,points:s.points.filter(p=>shown.includes(p.date)).map(p=>({...p,display:state.chartMode==='relative'?p.value-s.points[0].value:p.value}))}));let values=processed.flatMap(s=>s.points.map(p=>p.display));let min=Math.min(...values),max=Math.max(...values);if(!values.length){min=0;max=1;}if(max-min<2){min-=1;max+=1;}let pad=(max-min)*.18;return{series:processed,dates:shown,min:min-pad,max:max+pad};}
  function renderChartSvg(){const c=chartData();const width=1000,height=280,left=40,right=24,top=15,bottom=35;const x=date=>left+Math.max(0,c.dates.indexOf(date))/Math.max(1,c.dates.length-1)*(width-left-right);const y=value=>top+(c.max-value)/(c.max-c.min)*(height-top-bottom);let grid=Array.from({length:5},(_,i)=>{let value=c.min+(c.max-c.min)*i/4;let yy=y(value);return`<line class="chart-grid" x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}"/><text class="chart-axis-text" x="0" y="${yy+3}">${state.chartMode==='relative'&&value>0?'+':''}${value.toFixed(1)}</text>`}).join('');let labels=[0,Math.floor((c.dates.length-1)/3),Math.floor((c.dates.length-1)*2/3),c.dates.length-1].filter((n,i,a)=>a.indexOf(n)===i&&n>=0).map(n=>`<text class="chart-axis-text" x="${x(c.dates[n])}" y="${height-8}" text-anchor="${n===0?'start':n===c.dates.length-1?'end':'middle'}">${prettyDate(c.dates[n])}</text>`).join('');let lines=c.series.map(s=>{const own=s.id===state.user.id;let path=s.points.map((p,i)=>`${i?'L':'M'}${x(p.date).toFixed(1)},${y(p.display).toFixed(1)}`).join(' ');return`${own&&s.points.length?`<path class="chart-area" d="${path} L${x(s.points.at(-1).date)},${height-bottom} L${x(s.points[0].date)},${height-bottom}Z"/>`:''}<path class="chart-series ${own?'':'foreign'}" d="${path}"/>${own&&s.points.length?`<circle class="chart-dot" cx="${x(s.points.at(-1).date)}" cy="${y(s.points.at(-1).display)}" r="4.5"/>`:''}`;}).join('');return`<svg class="weight-chart" id="weight-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Weight history line chart. Use range and display controls above."><defs><linearGradient id="chart-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ff4937" stop-opacity=".12"/><stop offset="100%" stop-color="#ff4937" stop-opacity="0"/></linearGradient></defs>${grid}${labels}${lines}<g id="chart-scrub" hidden><line class="chart-crosshair" x1="0" x2="0" y1="${top}" y2="${height-bottom}"/><circle class="chart-dot" r="5" cx="0" cy="0"/></g></svg><div class="chart-tooltip" id="chart-tooltip" hidden></div>`;}
  function renderWeight(){const series=visibleSeries(),own=series.find(s=>s.id===state.user.id),points=own?.points||[],latest=points.at(-1),delta=latest?latest.value-points[0].value:0;$('#weight-view').innerHTML=`<div class="page-heading"><div><h1 class="page-title">Weight</h1><p class="subline">Body weight and change over time</p></div><button class="subtle-button" data-action="open-weight">${icon('plus')}<span>Weigh in</span></button></div><div class="chart-summary"><div><div class="chart-summary-label">Latest weigh-in${latest?` / ${prettyDate(latest.date)}`:''}</div><div class="chart-main-number">${latest?fmt(latest.value):'—'}<small>lb</small></div></div><div class="chart-change"><strong>${delta>0?'+':''}${delta.toFixed(1)} lb</strong><small>over ${state.chartRange} days</small></div></div><div class="chart-panel"><div class="chart-toolbar"><div class="pill-switch" aria-label="Weight chart mode"><button data-action="chart-mode" data-mode="relative" class="${state.chartMode==='relative'?'active':''}">Change</button><button data-action="chart-mode" data-mode="absolute" class="${state.chartMode==='absolute'?'active':''}">Body weight</button></div><div class="chart-toolbar-right"><div class="pill-switch" aria-label="Weight chart range">${[30,90].map(n=>`<button data-action="chart-range" data-range="${n}" class="${state.chartRange===n?'active':''}">${n} days</button>`).join('')}</div><button class="icon-button" data-action="chart-reset" aria-label="Reset chart zoom">${icon('reset')}</button><button class="icon-button" data-action="chart-collapse" aria-label="${state.chartExpanded?'Collapse':'Expand'} chart">${icon(state.chartExpanded?'collapse':'expand')}</button></div></div><div class="chart-content" ${state.chartExpanded?'':'hidden'}>${series.length?renderChartSvg():'<div class="empty-state">No weight entries in this range.<br>Add a weigh-in to start the chart.</div>'}</div><div class="chart-footer"><div class="chart-legend">${series.map(s=>`<span><i></i>${escape(s.name)}${s.id===state.user.id?' (you)':''}</span>`).join('')}</div><span class="chart-hint">Drag to explore. Scroll to zoom. Double-tap to reset.</span></div></div>`;bindChart();}
  function render(){document.documentElement.dataset.theme=state.theme;$('#profile-avatar').textContent=state.user?.emoji||state.user?.name?.[0]||'?';$('.theme-button').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#connection-state span').textContent=state.connection||(state.demo?'Preview':'Saved');$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));if(!state.ready){$('#today-view').innerHTML=`<div class="loading-state">${state.error?`<div class="boot-error"><h2>Connection unavailable</h2><p>${escape(state.error)}</p><button class="primary-button" data-action="retry">Try again</button><button class="text-button" data-action="open-reclaim">Reclaim this device</button></div>`:'<div class="loading-ring"></div><span>Getting your board ready…</span>'}</div>`;$$('.workspace').forEach(el=>el.hidden=el.dataset.view!=='today');return;}renderToday();renderBoard();renderHistory();renderWeight();const displayView=state.view==='overview'&&window.innerWidth<=760?'today':state.view;$('#main-content').classList.toggle('overview-layout',displayView==='overview');$$('.workspace').forEach(el=>{const active=displayView==='overview'?['today','board','weight'].includes(el.dataset.view):el.dataset.view===displayView;el.hidden=!active;el.classList.toggle('active',active);});$$('.dock-item,.nav-item').forEach(b=>{const active=b.dataset.viewTarget===displayView;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
  function navigate(view){if(!['today','board','history','weight','overview'].includes(view))return;state.view=view;render();window.scrollTo({top:0,behavior:'instant'});dispatch('navigate',{view});}
  function closeSheet(){const d=$('#action-sheet');if(d.open)d.close();sheetContext={};renderSaveRecovery();}
  function shell(title,subtitle,body){return`<div class="sheet-inner"><header class="sheet-header"><div><h2 id="sheet-title">${escape(title)}</h2>${subtitle?`<p>${escape(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-sheet" aria-label="Close dialog">${icon('close')}</button></header>${body}</div>`;}
  function openSheet(type,payload={}){sheetContext={type,...payload,instance:nextSaveId()};const date=payload.date||state.today;if(type==='catchup'&&payload.date&&payload.date>=state.today){notify('Use the food log to update today.');return;}const d=dayFor(date,payload.memberId);let html='';
    if(type==='meal'||type==='preset'){const p=payload.id?state.presets.find(x=>x.id===payload.id)||{}:type==='meal'?payload:{};let preset=type==='preset';html=shell(preset?(p.id?'Edit saved meal':'Save meal'):'Log food',preset?'Reusable meal preset':prettyDate(date,{weekday:'long',month:'short',day:'numeric'}),`<form data-form="${preset?'preset':'meal'}" data-date="${date}" data-id="${escape(p.id||'')}"><div class="form-field"><label class="input-label" for="meal-name">What did you have? <span>(optional)</span></label><input class="field" id="meal-name" name="name" maxlength="24" placeholder="Chicken rice bowl" value="${escape(p.name)}" autocomplete="off"></div><div class="field-grid"><div class="form-field"><label class="input-label" for="meal-calories">Calories</label><div class="field-unit-wrap"><input class="field large-field" id="meal-calories" name="calories" type="number" min="1" max="10000" step="1" required inputmode="numeric" placeholder="0" value="${p.calories??''}"><span class="field-unit">kcal</span></div></div><div class="form-field"><label class="input-label" for="meal-protein">Protein <span>(optional)</span></label><div class="field-unit-wrap"><input class="field large-field" id="meal-protein" name="protein" type="number" min="0" max="1000" step="0.1" inputmode="decimal" placeholder="0" value="${p.protein??''}"><span class="field-unit">g</span></div></div></div>${preset?`<div class="form-field"><label class="input-label" for="meal-note">Note <span>(optional)</span></label><input class="field" id="meal-note" name="note" maxlength="80" placeholder="2 scoops, with water" value="${escape(p.note)}"></div>`:''}<p class="form-error" role="alert"></p><div class="sheet-actions"><button class="primary-button full-width" type="submit" data-action="save-meal">${preset?'Save meal':'Log food'}${icon('arrow')}</button>${!preset?'<button type="button" class="save-preset-button" data-action="save-current-preset">Save as a preset instead</button>':''}</div></form>${!preset&&state.presets.length?`<div class="sheet-presets"><div class="quick-label">Saved meals</div><div class="preset-list">${presetChips()}</div></div>`:''}`);}
    else if(type==='weight'){html=shell('Log weight',prettyDate(date,{weekday:'long',month:'short',day:'numeric'}),`<form data-form="weight" data-date="${date}"><div class="form-field"><label class="input-label" for="weight-input">Body weight</label><div class="field-unit-wrap"><input class="field large-field" id="weight-input" name="value" type="number" min="50" max="600" step="0.1" inputmode="decimal" value="${d.weight||''}" placeholder="169.4" required><span class="field-unit">lb</span></div></div><p class="form-error" role="alert"></p><button class="primary-button full-width" type="submit">Save weigh-in ${icon('check')}</button><p class="daily-note">${state.user.weightPrivate?'Your weight is private.':'Visible to your group. Change this in settings.'}</p></form>`);}
    else if(type==='rest'){const adHoc=d.rest,scheduled=d.scheduledRest&&!d.rest;html=shell(d.workout?'Clear workout first':adHoc||scheduled?'Rest day':'Mark a rest day',prettyDate(date,{weekday:'long',month:'short',day:'numeric'}),d.workout?`<p class="status-note">This day already has a completed workout. Clear it before marking the day as rest.</p><button class="primary-button full-width" data-action="day-workout" data-date="${date}" data-member="${escape(state.user.id)}">Clear workout first ${icon('close')}</button>`:`<p class="status-note">${adHoc?'The day is marked as rest. Clear this marker to log a workout.':scheduled?'This is a scheduled rest day. You can still log a workout, or edit your future schedule.':'This marks the day as rest. Nutrition stays active.'}</p>${scheduled?`<button class="primary-button full-width" data-action="day-workout" data-date="${date}" data-member="${escape(state.user.id)}">Log workout instead ${icon('dumbbell')}</button><button class="text-button" data-action="open-settings" data-section="training">Edit rest schedule</button>`:`<button class="primary-button full-width" data-action="confirm-rest" data-date="${date}" data-rest="${!adHoc}">${adHoc?'Clear rest marker':'Mark rest day'} ${icon(adHoc?'dumbbell':'rest')}</button>`}`);}
    else if(type==='nutrition'){html=shell('Nutrition status',prettyDate(date),`<p class="status-note">${d.nutritionManual?'You manually marked nutrition complete. Your logged totals are shown separately.':'Mark the day complete without changing your logged calories or protein.'}</p><button class="primary-button full-width" data-action="confirm-nutrition" data-date="${date}" data-hit="${!d.nutritionManual}">${d.nutritionManual?'Undo completion':'Mark complete'} ${icon('check')}</button>`);}
    else if(type==='day'){const member=state.members.find(m=>m.id===payload.memberId)||state.members.find(m=>m.id===state.user.id);const editable=member?.id===state.user.id&&date<=state.today&&!d.prejoin&&!d.dataUnavailable&&d.editable!==false;html=shell(prettyDate(date,{weekday:'long',month:'short',day:'numeric'}),member?.name||'Your day',`<div class="day-detail-status"><span class="tag">${escape(d.dataUnavailable?'Unavailable':d.workout?(d.workoutType||'Workout complete'):d.vacation?'Vacation':d.paused?'Workouts paused':d.rest||d.scheduledRest?'Rest day':'No workout logged')}</span><span class="tag">${escape(nutritionText(d))}</span></div><div class="day-detail-metrics"><div><label>Calories</label><strong>${fmt(d.calories)} <small>/ ${fmt(goals(d).calories)}</small></strong></div><div><label>Protein</label><strong>${fmt(d.protein)} <small>/ ${fmt(goals(d).protein)} g</small></strong></div></div>${(d.meals||[]).map(m=>`<div class="day-meal-reference"><span>${escape(m.name||'Food entry')}</span><span>${fmt(m.calories)} kcal / ${fmt(m.protein)} g</span></div>`).join('')}${editable?`<div class="form-field historical-workout-type"><label class="input-label" for="historical-workout-type">Workout type</label><select class="field" id="historical-workout-type" data-change="day-workout-type" data-date="${date}" data-member="${escape(member?.id)}"><option value="">Select workout</option>${(state.user.workoutTypes||[]).map(t=>`<option value="${escape(t)}" ${d.workoutType===t?'selected':''}>${escape(t)}</option>`).join('')}</select></div><div class="day-detail-actions"><button class="secondary-button" data-action="day-workout" data-date="${date}" data-member="${escape(member?.id)}">${d.workout?'Clear workout':'Log workout'}</button><button class="secondary-button" data-action="set-rest" data-date="${date}">${d.rest||d.scheduledRest?'Clear rest':'Rest day'}</button><button class="secondary-button" data-action="day-nutrition" data-date="${date}">${d.nutritionManual?'Clear nutrition hit':'Mark nutrition hit'}</button>${date<state.today?`<button class="secondary-button" data-action="open-catchup" data-date="${date}">Edit nutrition</button>`:`<button class="secondary-button" data-action="open-meal">Log food</button>`}</div>`:'<p class="daily-note">This day is read-only.</p>'}`);}
    else if(type==='catchup'){const selected=payload.date||addDays(state.today,-1),day=dayFor(selected);sheetContext.date=selected;html=shell('Edit nutrition','Update a past day’s nutrition.',`<form data-form="catchup" data-date="${selected}"><div class="form-field"><label class="input-label" for="catchup-date">Selected day</label><div class="period-controls"><button type="button" class="icon-button" data-action="catchup-date" data-date="${addDays(selected,-1)}" aria-label="Previous day">${icon('left')}</button><input class="field" type="date" id="catchup-date" name="date" max="${addDays(state.today,-1)}" value="${selected}" data-change="catchup-date"><button type="button" class="icon-button" data-action="catchup-date" data-date="${addDays(selected,1)}" aria-label="Next day" ${selected>=addDays(state.today,-1)?'disabled':''}>${icon('chevron')}</button></div></div><div class="field-grid"><div class="form-field"><label class="input-label" for="catchup-calories">Total calories</label><input class="field large-field" id="catchup-calories" name="calories" type="number" min="0" max="10000" step="1" value="${day.calories||0}"></div><div class="form-field"><label class="input-label" for="catchup-protein">Total protein, g</label><input class="field large-field" id="catchup-protein" name="protein" type="number" min="0" max="1000" step="0.1" value="${day.protein||0}"></div></div><label class="settings-row"><span class="settings-row-label">Mark nutrition complete</span><input type="checkbox" name="nutritionHit" ${day.nutritionManual?'checked':''}></label>${(day.meals||[]).map(m=>`<div class="day-meal-reference"><span>${escape(m.name||'Food entry')}</span><span>${fmt(m.calories)} kcal</span></div>`).join('')}<p class="form-error" role="alert"></p><button class="primary-button full-width" type="submit">Save day ${icon('check')}</button></form>`);}
    else if(type==='reclaim'){html=shell('Reconnect device','Restore this device’s saved access.',`<p class="status-note">Your personal access is already stored on this device. Reconnect to continue logging.</p><form data-form="reclaim"><p class="form-error" role="alert"></p><button class="primary-button full-width" type="submit">Reconnect device ${icon('arrow')}</button></form>`);}
    $('#sheet-content').innerHTML=html;const dialog=$('#action-sheet');if(!dialog.open)dialog.showModal();syncOperationUI();}
  function openSettings(section){settingsInstance=nextSaveId();renderSettings();const drawer=$('#settings-drawer');if(!drawer.open)drawer.showModal();syncOperationUI();if(section)requestAnimationFrame(()=>$(`[data-settings-section="${section}"]`)?.scrollIntoView({block:'start',behavior:'smooth'}));}
  function renderSettings(){renderSettingsContent();syncOperationUI();}
  function renderSettingsContent(){const u=state.user;$('#settings-content').innerHTML=`<div class="settings-inner"><header class="sheet-header settings-header"><div><h2 id="settings-title">Settings</h2><p>Profile, goals and training schedule</p></div><button class="icon-button" data-action="close-settings" aria-label="Close settings">${icon('close')}</button></header><section class="settings-group" data-settings-section="nutrition"><h3>Nutrition</h3><form data-form="goals"><div class="field-grid"><div class="form-field"><label class="input-label" for="goal-direction">Goal</label><select class="field" id="goal-direction" name="goal">${['gain','maintain','lose'].map(x=>`<option value="${x}" ${u.goal===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div class="form-field"><label class="input-label" for="nutrition-mode">Track</label><select class="field" id="nutrition-mode" name="nutritionMode">${[['both','Calories & protein'],['protein','Protein only'],['manual','Manual completion']].map(([v,t])=>`<option value="${v}" ${u.nutritionMode===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field-grid"><div class="form-field"><label class="input-label" for="calorie-goal">Daily calories</label><input class="field" id="calorie-goal" name="calorieGoal" type="number" min="800" max="10000" value="${u.calorieGoal||0}" required></div><div class="form-field"><label class="input-label" for="protein-goal">Daily protein, g</label><input class="field" id="protein-goal" name="proteinGoal" type="number" min="0" max="500" value="${u.proteinGoal||0}" required></div></div><p class="form-error"></p><button class="secondary-button full-width" type="submit">Save targets</button></form></section><section class="settings-group" data-settings-section="presets"><h3>Saved meals</h3><div class="settings-presets-list">${state.presets.map(p=>`<div class="saved-preset-row"><div><strong>${escape(p.name||'Saved meal')}</strong><small>${fmt(p.calories)} kcal / ${fmt(p.protein)} g protein${p.note?` / ${escape(p.note)}`:''}</small></div><div class="small-row-actions"><button class="icon-button" data-action="open-preset" data-id="${escape(p.id)}" aria-label="Edit ${escape(p.name||'saved meal')}">${icon('edit')}</button><button class="icon-button" data-action="delete-preset" data-id="${escape(p.id)}" aria-label="Delete ${escape(p.name||'saved meal')}">${icon('trash')}</button></div></div>`).join('')||'<p>No saved meals yet.</p>'}</div><button class="secondary-button full-width" data-action="open-preset">Add saved meal</button></section><section class="settings-group" data-settings-section="training"><h3>Training plan</h3><span class="input-label">Scheduled rest days</span><div class="weekday-picks">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>`<button data-action="pick-rest-day" data-day="${i}" class="${u.restDays?.includes(i)?'active':''}" aria-pressed="${!!u.restDays?.includes(i)}">${x}</button>`).join('')}</div><button class="secondary-button full-width" data-action="save-rest-days">Save rest schedule</button><p>Changes start today. Earlier days keep their schedule.</p><div class="settings-row" style="margin-top:23px"><span class="settings-row-label">Pause workouts<small>Nutrition tracking stays active.</small></span><button class="toggle" role="switch" aria-label="Pause workouts" aria-checked="${!!u.paused}" data-action="toggle-pause"><i></i></button></div><span class="input-label">Workout types</span><div class="type-picks">${[...new Set(['Upper','Lower','Push','Pull','Legs','Full body','Cardio',...(u.workoutTypes||[])])].map(t=>`<button data-action="pick-workout-type" data-type="${escape(t)}" class="${u.workoutTypes?.includes(t)?'active':''}" aria-pressed="${!!u.workoutTypes?.includes(t)}">${escape(t)}</button>`).join('')}</div><button class="secondary-button full-width" data-action="save-workout-types">Save workout types</button></section><section class="settings-group"><h3>Vacation</h3><p>Vacation pauses both nutrition and workouts.</p>${(u.vacations||[]).map((v,i)=>`<div class="vacation-row"><span>${prettyDate(v.start)} – ${prettyDate(v.end)}</span><button class="icon-button" data-action="delete-vacation" data-index="${i}" aria-label="Remove vacation ${i+1}">${icon('close')}</button></div>`).join('')}<form data-form="vacation"><div class="field-grid"><div class="form-field"><label class="input-label" for="vacation-start">First day</label><input class="field" type="date" id="vacation-start" name="start" required></div><div class="form-field"><label class="input-label" for="vacation-end">Last day</label><input class="field" type="date" id="vacation-end" name="end" required></div></div><p class="form-error"></p><button class="secondary-button full-width" type="submit">Add vacation</button></form></section><section class="settings-group"><h3>Profile & privacy</h3><form data-form="profile"><div class="form-field"><label class="input-label" for="profile-name">Display name</label><input class="field" id="profile-name" name="name" maxlength="24" value="${escape(u.name)}" required></div><div class="form-field"><label class="input-label" for="rollover-hour">Your day starts at</label><select class="field" id="rollover-hour" name="rolloverHour">${Array.from({length:24},(_,h)=>`<option value="${h}" ${u.rolloverHour===h?'selected':''}>${h%12||12}:00 ${h<12?'AM':'PM'}</option>`).join('')}</select></div><div class="settings-row"><span class="settings-row-label">Keep weight private<small>Only you can see your weigh-ins.</small></span><button type="button" class="toggle" role="switch" aria-label="Keep weight private" aria-checked="${!!u.weightPrivate}" data-action="toggle-privacy"><i></i></button></div><p class="form-error"></p><button class="secondary-button full-width" type="submit">Save profile</button></form></section></div>`;}
  function bindChart(){if(!window.GymBoardChart)return;window.GymBoardChart.bind({host:$('.chart-content'),svg:()=>$('#weight-chart'),getData:chartData,getView:()=>({zoom:chartZoom,pan:chartPan}),setView:({zoom,pan})=>{chartZoom=zoom;chartPan=pan;$('.chart-content').innerHTML=renderChartSvg();}});}
  document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const dispatch=(action,payload)=>window.GymBoardUI.dispatch(action,payload,b);const a=b.dataset.action;if(b.type==='submit'&&b.closest('form'))return;event.preventDefault();const date=b.dataset.date||state.today;const d=dayFor(date,b.dataset.member);
    switch(a){case'recover-save':recoverSave(b.dataset.operationId);break;case'navigate':navigate(b.dataset.viewTarget);break;case'toggle-theme':state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('gymboard.theme',state.theme);render();break;case'open-settings':if($('#action-sheet').open)closeSheet();openSettings(b.dataset.section);break;case'close-settings':$('#settings-drawer').close();break;case'close-sheet':closeSheet();break;case'open-meal':openSheet('meal',b.dataset.fromQuick?{date,...quickMealDraft,fromQuick:true}:{date});break;case'open-preset':openSheet('preset',{id:b.dataset.id});break;case'open-weight':openSheet('weight',{date});break;case'open-catchup':openSheet('catchup',{date:b.dataset.date||addDays(state.today,-1)});break;case'catchup-date':if(date<state.today)openSheet('catchup',{date});break;case'open-reclaim':openSheet('reclaim');break;case'retry':dispatch('retry');break;case'log-preset':dispatch('log-preset',{id:b.dataset.id,date:sheetContext.date||state.today});break;case'delete-meal':dispatch('delete-meal',{id:b.dataset.id,date});break;case'delete-preset':dispatch('delete-preset',{id:b.dataset.id});break;case'nutrition-options':openSheet('nutrition',{date});break;case'toggle-nutrition':case'day-nutrition':dispatch('set-nutrition',{date,hit:!d.nutritionManual});break;case'confirm-nutrition':dispatch('set-nutrition',{date,hit:b.dataset.hit==='true'});break;case'toggle-workout':if(d.workout)dispatch('set-workout',{date,complete:false,type:d.workoutType||''});else if(d.vacation)openSettings('training');else if(d.paused)dispatch('set-pause',{paused:false});else if(d.rest)openSheet('rest',{date});else dispatch('set-workout',{date,complete:!d.workout,type:d.workoutType||''});break;case'day-workout':if(d.rest&&!d.workout)openSheet('rest',{date});else dispatch('set-workout',{date,complete:!d.workout,type:d.workoutType||'',memberId:b.dataset.member});break;case'set-rest':openSheet('rest',{date});break;case'confirm-rest':dispatch('set-rest',{date,rest:b.dataset.rest==='true'});break;case'resume-workouts':dispatch('set-pause',{paused:false});break;case'toggle-pause':dispatch('set-pause',{paused:!state.user.paused});break;case'toggle-privacy':dispatch('set-privacy',{weightPrivate:!state.user.weightPrivate});break;case'pick-rest-day':case'pick-workout-type':b.classList.toggle('active');b.setAttribute('aria-pressed',b.classList.contains('active'));break;case'save-rest-days':dispatch('save-rest-days',{days:$$('.weekday-picks button.active').map(x=>Number(x.dataset.day))});break;case'save-workout-types':dispatch('save-workout-types',{types:$$('.type-picks button.active').map(x=>x.dataset.type)});break;case'delete-vacation':dispatch('delete-vacation',{index:Number(b.dataset.index)});break;case'change-week':state.weekOffset=Number(b.dataset.offset);dispatch('change-week',{offset:state.weekOffset});break;case'change-month':{const dt=dateObj(`${state.historyMonth}-01`);dt.setMonth(dt.getMonth()+Number(b.dataset.direction));state.historyMonth=dateKey(dt).slice(0,7);dispatch('change-month',{month:state.historyMonth});break;}case'select-date':state.selectedDate=date;renderHistory();break;case'open-day':openSheet('day',{date,memberId:b.dataset.member});break;case'chart-mode':state.chartMode=b.dataset.mode;renderWeight();break;case'chart-range':state.chartRange=Number(b.dataset.range);chartZoom=1;chartPan=0;renderWeight();break;case'chart-reset':chartZoom=1;chartPan=0;renderWeight();break;case'chart-collapse':state.chartExpanded=!state.chartExpanded;renderWeight();break;case'save-current-preset':{const f=b.closest('form');if(!f.reportValidity())return;const data=new FormData(f);dispatch('save-preset',{name:data.get('name')||'',calories:Number(data.get('calories')),protein:Number(data.get('protein')||0),note:''});break;}}
  });
  document.addEventListener('change',event=>{const el=event.target;const dispatch=(action,payload)=>window.GymBoardUI.dispatch(action,payload,el);switch(el.dataset.change){case'workout-type':dispatch('set-workout',{date:state.today,complete:true,type:el.value});break;case'day-workout-type':dispatch('set-workout',{date:el.dataset.date,memberId:el.dataset.member,complete:true,type:el.value});break;case'history-member':state.historyMember=el.value;dispatch('change-member',{id:el.value});break;case'catchup-date':if(el.value&&el.value<state.today)openSheet('catchup',{date:el.value});break;}});
  document.addEventListener('input',event=>{const el=event.target;if(el.closest('[data-quick-meal]')&&['name','calories','protein'].includes(el.name))quickMealDraft[el.name]=el.value;});
  document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const date=values.date||form.dataset.date||state.today;const error=$('.form-error',form);if(error)error.textContent='';let action,payload;switch(form.dataset.form){case'meal':case'preset':{const calories=Number(values.calories),protein=Number(values.protein||0);if(!Number.isFinite(calories)||!Number.isFinite(protein)||calories<0||protein<0||(!calories&&!protein)){error.textContent='Enter calories or protein above zero.';return;}action=form.dataset.form==='meal'?'add-meal':'save-preset';payload={name:values.name||'',calories,protein,note:values.note||'',date};if(form.dataset.id)payload.id=form.dataset.id;break;}case'weight':action='save-weight';payload={date,value:Number(values.value)};break;case'goals':action='save-goals';payload={goal:values.goal,nutritionMode:values.nutritionMode,calorieGoal:Number(values.calorieGoal),proteinGoal:Number(values.proteinGoal)};break;case'profile':action='save-profile';payload={name:values.name.trim(),rolloverHour:Number(values.rolloverHour)};break;case'vacation':if(values.end<values.start){error.textContent='The last day must be on or after the first day.';return;}action='add-vacation';payload={start:values.start,end:values.end};break;case'catchup':{const day=dayFor(date),floor=(day.meals||[]).reduce((a,m)=>({calories:a.calories+Number(m.calories||0),protein:a.protein+Number(m.protein||0)}),{calories:0,protein:0});if((values.calories!==''&&Number(values.calories)<floor.calories)||(values.protein!==''&&Number(values.protein)<floor.protein)){error.textContent=`Totals must include recorded meals: at least ${fmt(floor.calories)} kcal and ${fmt(floor.protein)} g protein.`;return;}action='save-catchup';payload={date,calories:values.calories===''?undefined:Number(values.calories),protein:values.protein===''?undefined:Number(values.protein),nutritionHit:values.nutritionHit==='on'};break;}case'reclaim':action='reclaim';payload={};break;}if(action)dispatch(action,payload,form);});
  [$('#action-sheet'),$('#settings-drawer')].forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));
  function demoAction(action,p){if(!state.demo)return;const day=p.date?dayFor(p.date):state.day;let message='Saved';switch(action){case'add-meal':{const meal={...p,id:`m${Date.now()}`,time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})};day.meals=[...(day.meals||[]),meal];day.calories+=p.calories;day.protein+=p.protein;message='Food logged';closeSheet();break;}case'delete-meal':{const m=day.meals.find(x=>x.id===p.id);if(m){day.calories=Math.max(0,day.calories-m.calories);day.protein=Math.max(0,day.protein-m.protein);day.meals=day.meals.filter(x=>x.id!==p.id);}message='Food entry removed';break;}case'log-preset':{const preset=state.presets.find(x=>x.id===p.id);if(preset)demoAction('add-meal',{...preset,date:p.date});return;}case'save-preset':{const saved={...p,id:p.id||`p${Date.now()}`};state.presets=p.id?state.presets.map(x=>x.id===p.id?saved:x):[...state.presets,saved];message='Meal preset saved';closeSheet();break;}case'delete-preset':state.presets=state.presets.filter(x=>x.id!==p.id);message='Saved meal removed';break;case'set-workout':day.workout=p.complete;day.workoutType=p.type;day.rest=false;message=p.complete?'Workout complete. Saved.':'Workout completion undone';closeSheet();break;case'set-rest':day.rest=p.rest;day.scheduledRest=false;if(p.rest)day.workout=false;message=p.rest?'Rest day marked':'Rest day cleared';closeSheet();break;case'set-nutrition':day.nutritionHit=p.hit;day.nutritionManual=p.hit;message=p.hit?'Nutrition marked complete':'Nutrition completion undone';closeSheet();break;case'save-weight':day.weight=p.value;day.weightDate=p.date;{let own=state.weights.find(w=>w.id===state.user.id);if(own){own.points=own.points.filter(x=>x.date!==p.date);own.points.push({date:p.date,value:p.value});own.points.sort((a,b)=>a.date.localeCompare(b.date));}}message='Weigh-in saved';closeSheet();break;case'save-goals':Object.assign(state.user,p);message='Targets saved';break;case'save-rest-days':state.user.restDays=p.days;message='Rest schedule saved';break;case'set-pause':state.user.paused=p.paused;state.day.paused=p.paused;message=p.paused?'Workouts paused':'Workouts resumed';break;case'save-workout-types':state.user.workoutTypes=p.types;message='Workout types saved';break;case'add-vacation':state.user.vacations.push(p);message='Vacation added';break;case'delete-vacation':state.user.vacations.splice(p.index,1);message='Vacation removed';break;case'set-privacy':state.user.weightPrivate=p.weightPrivate;message=p.weightPrivate?'Your weight is private':'Your weight is shared';break;case'save-profile':Object.assign(state.user,p);message='Profile saved';break;case'save-catchup':Object.assign(day,p,{nutritionManual:p.nutritionHit});message='Day updated';closeSheet();break;case'change-week':refreshDemoWeek();render();return;case'change-month':case'change-member':renderHistory();return;case'navigate':return;default:return;}render();if($('#settings-drawer').open)renderSettings();notify(message);}

  function refreshSettingsAfterAction(action){
    if(!$('#settings-drawer').open)return;
    const resetForm={'save-goals':'goals','save-profile':'profile','add-vacation':'vacation'}[action];
    const drafts=$$('[data-form]',$('#settings-drawer')).filter(f=>f.dataset.form!==resetForm).map(f=>({name:f.dataset.form,fields:[...f.elements].filter(x=>x.name).map(x=>({name:x.name,value:x.value,checked:x.checked}))}));
    const rest=$$('.weekday-picks button.active').map(b=>b.dataset.day),types=$$('.type-picks button.active').map(b=>b.dataset.type),scroll=$('#settings-drawer').scrollTop;
    const focus=document.activeElement?.id;
    renderSettings();
    drafts.forEach(d=>{const f=$(`[data-form="${d.name}"]`,$('#settings-drawer'));d.fields.forEach(v=>{const el=f?.elements.namedItem(v.name);if(el){el.value=v.value;if(el.type==='checkbox')el.checked=v.checked;}});});
    if(action!=='save-rest-days')$$('.weekday-picks button').forEach(b=>{b.classList.toggle('active',rest.includes(b.dataset.day));b.setAttribute('aria-pressed',rest.includes(b.dataset.day));});
    if(action!=='save-workout-types')$$('.type-picks button').forEach(b=>{b.classList.toggle('active',types.includes(b.dataset.type));b.setAttribute('aria-pressed',types.includes(b.dataset.type));});
    $('#settings-drawer').scrollTop=scroll;
    if(focus&&document.getElementById(focus))document.getElementById(focus).focus({preventScroll:true});
  }
  window.addEventListener('gymboard:action-complete',event=>{
    const {action,status,message,payload}=event.detail||{};
    const op=saveOperations.get(payload?._operationId);
    if(!op)return;
    op.status=status;op.message=message;
    if(status==='pending'){syncOperationUI();return;}
    const form=operationForm(op);
    if(form)setFormBusy(form,op);
    if(status==='error'||status==='partial'){
      if(!op.formType){saveOperations.delete(op.id);notify(message||'Could not save. Try again.',true);}
      syncOperationUI();return;
    }
    if(status!=='saved')return;
    saveOperations.delete(op.id);
    if(action==='add-meal'&&(op.quick||op.fromQuick)&&['name','calories','protein'].every(key=>String(quickMealDraft[key]??'')===String(op.quickDraft[key]??'')))quickMealDraft={name:'',calories:'',protein:''};
    if(op.quick||op.fromQuick)renderToday();
    if(op.sheetInstance&&$('#action-sheet').open&&sheetContext.instance===op.sheetInstance)closeSheet();
    if(op.parentSettings===settingsInstance&&$('#settings-drawer').open)refreshSettingsAfterAction(action);
    if(action==='set-workout'&&payload.complete){const control=$('.workout-orb');control?.classList.add('just-completed');setTimeout(()=>control?.classList.remove('just-completed'),650);}
    syncOperationUI();
  });
  [$('#action-sheet'),$('#settings-drawer')].forEach(dialog=>dialog.addEventListener('close',()=>renderSaveRecovery()));

  function showDayHover(button){
    if(button.dataset.member===state.user.id||!matchMedia('(hover:hover)').matches)return;
    const member=state.members.find(m=>m.id===button.dataset.member),d=dayFor(button.dataset.date,button.dataset.member),tip=$('#day-hover-preview');
    tip.innerHTML=`<strong>${escape(member?.name)} / ${prettyDate(button.dataset.date)}</strong><div>${escape(d.workoutStatus||(d.workout?'Workout complete':d.rest?'Rest':'Not logged'))}</div><div>${escape(nutritionText(d))}</div><span>${fmt(d.calories)} / ${fmt(goals(d).calories)} kcal</span><span>${fmt(d.protein)} / ${fmt(goals(d).protein)} g protein</span>`;
    tip.hidden=false;const r=button.getBoundingClientRect(),width=tip.offsetWidth,height=tip.offsetHeight;
    tip.style.left=`${Math.max(12,Math.min(innerWidth-width-12,r.left+r.width/2-width/2))}px`;
    tip.style.top=`${r.bottom+height+10>innerHeight?r.top-height-8:r.bottom+8}px`;
    button.setAttribute('aria-describedby','day-hover-preview');
  }
  document.addEventListener('pointerover',event=>{const b=event.target.closest('.board-cell');if(b)showDayHover(b);});
  document.addEventListener('pointerout',event=>{const b=event.target.closest('.board-cell');if(b&&!b.contains(event.relatedTarget)){$('#day-hover-preview').hidden=true;b.removeAttribute('aria-describedby');}});
  document.addEventListener('focusin',event=>{if(event.target.matches('.board-cell'))showDayHover(event.target);});
  document.addEventListener('focusout',event=>{if(event.target.matches('.board-cell')){$('#day-hover-preview').hidden=true;event.target.removeAttribute('aria-describedby');}});
  let viewportMobile=innerWidth<=760;
  window.addEventListener('resize',()=>{const next=innerWidth<=760;if(next!==viewportMobile){viewportMobile=next;if(state.view==='overview')render();}});

  window.GymBoardUI={get state(){return state;},setState(patch){state={...state,...patch};render();},render,notify,openSheet,closeSheet,openSettings,navigate,dispatch,escape,icon,dayFor};
  render();window.dispatchEvent(new CustomEvent('gymboard:ready'));
})();
